import {
  IsNotEmpty,
  IsOptional,
  IsString,
  Matches,
  MaxLength,
} from 'class-validator';
import { Trim, TrimToNull } from '../../common/transforms.js';
import { IfSent, IsCalendarDate } from '../../common/validation.js';

/** Digits with optional spaces, dots or dashes and a leading +; 8–20 characters. */
const PHONE = /^\+?\d[\d .-]{6,18}\d$/;
const PHONE_MESSAGE =
  'Phone number must be 8–20 characters: digits, spaces, dots, dashes and an optional leading +.';

/** FR-15: full name is mandatory; the code is generated by the service. */
export class CreateCustomerDto {
  @Trim()
  @IsString()
  @IsNotEmpty({ message: 'Full name is required.' })
  @MaxLength(200)
  fullName: string;

  @IsOptional()
  @TrimToNull()
  @IsString()
  @Matches(PHONE, { message: PHONE_MESSAGE })
  @MaxLength(30)
  phone?: string | null;

  @IsOptional()
  @IsCalendarDate()
  dateOfBirth?: string;

  @IsOptional()
  @TrimToNull()
  @IsString()
  @MaxLength(300)
  address?: string | null;
}

/** Every field optional; a field left out is not changed, "" clears an optional one. */
export class UpdateCustomerDto {
  @IfSent()
  @Trim()
  @IsString()
  @IsNotEmpty({ message: 'Full name is required.' })
  @MaxLength(200)
  fullName?: string;

  @IsOptional()
  @TrimToNull()
  @IsString()
  @Matches(PHONE, { message: PHONE_MESSAGE })
  @MaxLength(30)
  phone?: string | null;

  @IsOptional()
  @IsCalendarDate()
  dateOfBirth?: string | null;

  @IsOptional()
  @TrimToNull()
  @IsString()
  @MaxLength(300)
  address?: string | null;
}

export class ListCustomersQuery {
  /** Matches full name, customer code or phone number. */
  @IsOptional()
  @Trim()
  @IsString()
  @MaxLength(100)
  search?: string;
}
